describe("WeightBasedShippingCalculator", () => {
  it("throws when no brackets provided", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("throws on invalid bracket upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws on invalid bracket costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws on invalid overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 3)], 1000)).toBe(0);
  });

  it("selects the correct bracket based on weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);
    // 200g item, qty 2 = 400g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 2, 200)], 1000)).toBe(300);
    // 500g item, qty 1 = 500g → first bracket (<=500)
    expect(calc.computeShippingCents([makeLine("b", 1, 500)], 1000)).toBe(300);
    // 600g → second bracket
    expect(calc.computeShippingCents([makeLine("c", 1, 600)], 1000)).toBe(500);
    // 3000g → third bracket
    expect(calc.computeShippingCents([makeLine("d", 3, 1000)], 1000)).toBe(1000);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([makeLine("a", 5, 500)], 1000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5, 500)], 1000)).toBe(500);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    // 400g → should hit first sorted bracket (500)
    expect(calc.computeShippingCents([makeLine("a", 2, 200)], 1000)).toBe(300);
  });
});

