      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal=1000, discount=500, discounted=500, tax=floor(500*0.1)=50
    expect(result.totals.taxCents).toBe(50);
    expect(result.totals.discountCents).toBe(500);
  });

  it("runs full pipeline: fetch → inventory → async tax", async () => {
