      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });

    // refreshed price=300 * qty=2 = 600, no discount, tax=floor(600*0.05)=30
    expect(result.totals.subtotalCents).toBe(600);
    expect(result.totals.taxCents).toBe(30);
    expect(result.totals.totalCents).toBe(630);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 5000])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("throws on invalid percent values", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("allows boundary values 0 and 100", () => {
    expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
  });

  it.each([
    [10, 1000, 100],
    [25, 999, 249],
    [50, 1, 0],
    [100, 5000, 5000],
    [0, 5000, 0],
  ])(
    "%i%% of %i cents = %i cents discount",
    (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    },
  );

  it("returns 0 when subtotal is zero or negative", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("throws on invalid amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new FixedAmountDiscountPolicy(1.5)).toThrow(RangeError);
  });

  it("allows 0 as amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
  });

  it.each([
    [500, 1000, 500],
    [500, 300, 300],
    [0, 1000, 0],
    [1000, 1000, 1000],
  ])(
    "fixed %i off subtotal %i = %i discount",
    (amount, subtotal, expected) => {
      const policy = new FixedAmountDiscountPolicy(amount);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    },
  );

  it("returns 0 when subtotal is zero or negative", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws when given no policies", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 => total 300
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child values to 0", () => {
      const negative = { computeDiscountCents: () => -50 };
      const policy = new CompositeDiscountPolicy(
        [negative, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, + 100 = 100
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 50% of 1000 = 500, then 50% of remaining 500 = 250 => total 750
      expect(policy.computeDiscountCents(1000)).toBe(750);
    });

    it("stops accumulating when remaining hits 0", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // first takes all 1000, remaining=0, second gets 0
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child values to 0 and caps at remaining", () => {
      const negative = { computeDiscountCents: () => -100 };
      const policy = new CompositeDiscountPolicy(
        [negative, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative clamped to 0, remaining stays 500, fixed takes 200
      expect(policy.computeDiscountCents(500)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const policy = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(policy.computeDiscountCents(1000)).toBe(300);
  });
});

