    cart = new Cart();
  });

  it("adds a product and tracks item count", () => {
    cart.add(product(), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("accumulates quantity for same product", () => {
    cart.add(product(), 1);
    cart.add(product(), 3);
    expect(cart.itemCount).toBe(4);
