  it("throws on negative quantity in updateQuantity", () => {
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("prod-1", -1)).toThrow(RangeError);
  });

  it("throws on non-integer quantity in updateQuantity", () => {
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("prod-1", 1.5)).toThrow(RangeError);
  });

  it("throws when updating non-existent product", () => {
    expect(() => cart.updateQuantity("nope", 5)).toThrow();
  });

  it("clears all items", () => {
    cart.add(product(), 1);
    cart.add(product({ id: "prod-2" }), 2);
