  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product(), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy: mockDiscount, region: "US-CA" });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(87); // floor(1000 * 0.0875)
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart();
    cart.add(product(), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("applies discount before async tax calculation", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal=1000, discount=500, discounted=500, tax=floor(500*0.1)=50
    expect(result.totals.taxCents).toBe(50);
    expect(result.totals.discountCents).toBe(500);
  });

  it("runs full pipeline: fetch → inventory → async tax", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(product({ unitPriceCents: 100 }), 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(300),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });

    // refreshed price=300 * qty=2 = 600, no discount, tax=floor(600*0.05)=30
    expect(result.totals.subtotalCents).toBe(600);
    expect(result.totals.taxCents).toBe(30);
    expect(result.totals.totalCents).toBe(630);
  });
});
